def case_witnesses(public):
    result = []
    facts = public.get('facts')
    question = public.get('question')
    if type(facts) is str and facts:
        result.append({'field': 'facts', 'quote': facts})
    if type(question) is str and question:
        result.append({'field': 'question', 'quote': question})
    return result


def supported(record, public):
    if type(record) is not dict:
        return False
    field = record.get('source_field')
    quote = record.get('quote')
    text = public.get(field)
    return field in ('facts', 'question') and type(quote) is str and bool(quote) and type(text) is str and quote in text


def projected(owner, relation, relative, employer, employee):
    result = []
    if not all(type(value) is str for value in [owner, relation, relative, employer, employee]):
        return result
    rel = relation.casefold()
    if relative == employer and owner == employee:
        if rel in ('wife', 'husband', 'spouse'):
            result.append('spouse')
        elif rel == 'child':
            result.extend(['son', 'daughter'])
        elif rel == 'parent':
            result.extend(['father', 'mother'])
        else:
            result.append(rel)
    elif owner == employer and relative == employee:
        if rel in ('father', 'mother', 'parent'):
            result.extend(['son', 'daughter'])
        elif rel in ('son', 'daughter', 'child'):
            result.extend(['father', 'mother'])
        elif rel in ('wife', 'husband', 'spouse'):
            result.append('spouse')
    return result


def apply(inputs, premises):
    public = inputs.get('public_case', {})
    literal = inputs.get('literal_context', {})
    values = literal.get('values', {}) if type(literal) is dict else {}
    witnesses = case_witnesses(public)
    unresolved = set()
    bindings = []
    seen = set()
    employer = values.get('employer')
    employee = values.get('employee')
    question = public.get('question')
    service = None
    if type(employer) is str and type(employee) is str and type(question) is str:
        folded = ' ' + question.casefold() + ' '
        if ' employing ' in folded:
            service = True
    literal_relations = values.get('case_family_relations')
    direct_relationships = []
    if type(literal_relations) is list:
        for triple in literal_relations:
            if type(triple) is list and len(triple) == 3:
                direct_relationships.extend(projected(triple[0], triple[1], triple[2], employer, employee))
    if type(service) is bool and direct_relationships and witnesses:
        for relationship in direct_relationships:
            key = (service, relationship)
            if key not in seen:
                seen.add(key)
                bindings.append({'inputs': {'service_performed_in_employ': service, 'employer_relationship_to_employee': relationship}, 'witnesses': witnesses})
        return {'bindings': bindings, 'unresolved': []}
    observation = inputs.get('observation')
    if type(observation) is not dict or type(observation.get('views')) is not list:
        return {'bindings': [], 'unresolved': ['A source-backed factual observation is required to ground the employment and relationship roles.']}
    for view in observation.get('views'):
        if type(view) is not dict:
            unresolved.add('A factual view was not a declared record.')
            continue
        view_employer = employer
        view_employee = employee
        view_service = service
        employment = view.get('employment')
        if type(employment) is dict:
            if supported(employment, public):
                if type(view_employer) is not str:
                    view_employer = employment.get('employer')
                elif view_employer != employment.get('employer'):
                    unresolved.add('The observed employer conflicts with the literal question role.')
                if type(view_employee) is not str:
                    view_employee = employment.get('employee')
                elif view_employee != employment.get('employee'):
                    unresolved.add('The observed employee conflicts with the literal question role.')
                if type(view_service) is not bool:
                    view_service = employment.get('service_performed_in_employ')
            else:
                unresolved.add('An employment observation lacks a current verbatim witness.')
        relation_rows = []
        if type(literal_relations) is list:
            for triple in literal_relations:
                if type(triple) is list and len(triple) == 3:
                    relation_rows.append({'owner': triple[0], 'relationship': triple[1], 'relative': triple[2]})
        observed_relations = view.get('family_relations')
        if type(observed_relations) is list:
            for row in observed_relations:
                if supported(row, public):
                    relation_rows.append(row)
                else:
                    unresolved.add('A family-relation observation lacks a current verbatim witness.')
        relationships = []
        for row in relation_rows:
            relationships.extend(projected(row.get('owner'), row.get('relationship'), row.get('relative'), view_employer, view_employee))
        if view.get('relation_extraction_status') != 'resolved':
            unresolved.add('Family-relation extraction remains unknown or failed.')
        if type(view_employer) is not str or type(view_employee) is not str:
            unresolved.add('The current employer and employee roles are not both grounded.')
        if type(view_service) is not bool:
            unresolved.add('Whether service was performed in the identified employ is not grounded.')
        if not relationships:
            unresolved.add('The employer relationship to the employee cannot be projected from a positive relation statement.')
        if type(view_service) is bool and relationships and witnesses:
            for relationship in relationships:
                key = (view_service, relationship)
                if key not in seen:
                    seen.add(key)
                    bindings.append({'inputs': {'service_performed_in_employ': view_service, 'employer_relationship_to_employee': relationship}, 'witnesses': witnesses})
    return {'bindings': bindings, 'unresolved': sorted(unresolved)}

